import random
import math

def get_edges():
    edges = []
    for g in range(8):
        base = 3*g
        edges.append((base, base+1))
        edges.append((base, base+2))
        edges.append((base+1, base+2))
    for g in range(7):
        for i in range(3):
            edges.append((3*g+i, 3*(g+1)+i))
    return edges

edges = get_edges()
n = 24
m = 45

def compute_conflict_score(labels):
    diff_count = {}
    for u, v in edges:
        d = abs(labels[u] - labels[v])
        diff_count[d] = diff_count.get(d, 0) + 1
    return sum(v - 1 for v in diff_count.values() if v > 1)

def simulated_annealing_v2(max_iter=3000000, T_start=2.0, T_end=0.01, seed=None):
    if seed is not None:
        random.seed(seed)

    all_labels = list(range(m+1))
    random.shuffle(all_labels)
    labels = all_labels[:n]

    current_score = compute_conflict_score(labels)
    best_score = current_score
    best_labels = labels[:]

    cooling = (T_end / T_start) ** (1.0 / max_iter)
    T = T_start

    for iteration in range(max_iter):
        if best_score == 0:
            return best_labels

        # Random swap
        i = random.randint(0, n-1)
        j = random.randint(0, n-1)
        while j == i:
            j = random.randint(0, n-1)

        labels[i], labels[j] = labels[j], labels[i]
        new_score = compute_conflict_score(labels)

        delta = new_score - current_score
        if delta < 0 or random.random() < math.exp(-delta / T):
            current_score = new_score
            if new_score < best_score:
                best_score = new_score
                best_labels = labels[:]
        else:
            labels[i], labels[j] = labels[j], labels[i]

        T *= cooling

        if iteration % 500000 == 0:
            print(f"Iter {iteration}: T={T:.6f}, current={current_score}, best={best_score}")

    return best_labels if best_score == 0 else None

# Try multiple seeds
for seed in range(20):
    result = simulated_annealing_v2(3000000, T_start=3.0, T_end=0.001, seed=seed)
    if result:
        print(f"Found with seed {seed}:", result)
